-- =============================================================================
-- Spa Rivier: the rest of the site is edited in the admin (2026-10-14)
--
-- Until now the admin edited the Salon and Spa prices, the promotions and the
-- Boutique brands; everything else needed a code change. This file adds what
-- the admin needs for the rest:
--   1. site_text — the page text the admin has changed, by its key in
--      src/i18n/en.json and fr.json (contact details and hours included);
--   2. site_photos — the page photos the admin has replaced, by their address
--      in the code (src/data/photoSlots.js);
--   3. site_items — the lists edited item by item: Haircare, Skincare and
--      Bath & Body brands, Team profiles, the Spa FAQ, and What's Happening's
--      events, promo of the day and articles (src/data/siteLists.js), with
--      the items the site showed on 2026-10-14 copied in;
--   4. MediSpa prices in the services table (category 'medispa', with the
--      price of a series of 8), copied from src/data/medispaData.js;
--   5. a public "site" storage bucket the admin uploads photos to;
--   6. profiles.studio_access — who may open Supabase Studio through the
--      admin login (see functions/studio-gate). Only someone who already has
--      it, or the database itself, may give or take it away.
--
-- Safe to run more than once: rows are copied in only while their table (or
-- list) is empty, so later admin edits are kept.
-- Run it BEFORE deploying the site that reads these tables:
--   docker exec -i supabase-db psql -U postgres -d postgres < site-editing.sql
-- =============================================================================

SET client_encoding = 'UTF8';

BEGIN;

-- ── 1. Page text ─────────────────────────────────────────────────────────────
-- A blank en or fr means "the wording in the file" for that language.
CREATE TABLE IF NOT EXISTS public.site_text (
  key         text        PRIMARY KEY,
  en          text        NOT NULL DEFAULT '',
  fr          text        NOT NULL DEFAULT '',
  updated_at  timestamptz NOT NULL DEFAULT now(),
  updated_by  uuid        DEFAULT auth.uid() REFERENCES auth.users(id) ON DELETE SET NULL
);

-- ── 2. Page photos ───────────────────────────────────────────────────────────
CREATE TABLE IF NOT EXISTS public.site_photos (
  slot        text        PRIMARY KEY,
  url         text        NOT NULL,
  updated_at  timestamptz NOT NULL DEFAULT now(),
  updated_by  uuid        DEFAULT auth.uid() REFERENCES auth.users(id) ON DELETE SET NULL
);

-- ── 3. Lists ─────────────────────────────────────────────────────────────────
CREATE TABLE IF NOT EXISTS public.site_items (
  id          uuid        PRIMARY KEY DEFAULT gen_random_uuid(),
  list        text        NOT NULL CHECK (list IN ('haircare','skincare','bathbody','bathbody_accessories',
                                                   'team','spa_faq','events','daily_promos','articles')),
  slug        text        NOT NULL,
  data        jsonb       NOT NULL DEFAULT '{}'::jsonb,
  active      boolean     NOT NULL DEFAULT true,
  sort_order  integer     NOT NULL DEFAULT 0,
  created_at  timestamptz NOT NULL DEFAULT now(),
  UNIQUE (list, slug)
);
CREATE INDEX IF NOT EXISTS idx_site_items_list ON public.site_items(list, sort_order);

-- Everyone reads; only admins write. site_items shows visitors only shown items.
ALTER TABLE public.site_text   ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.site_photos ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.site_items  ENABLE ROW LEVEL SECURITY;
GRANT SELECT ON public.site_text, public.site_photos, public.site_items TO anon, authenticated;
GRANT INSERT, UPDATE, DELETE ON public.site_text, public.site_photos, public.site_items TO authenticated;

DROP POLICY IF EXISTS "site_text: public read"        ON public.site_text;
DROP POLICY IF EXISTS "site_text: admins all"         ON public.site_text;
DROP POLICY IF EXISTS "site_photos: public read"      ON public.site_photos;
DROP POLICY IF EXISTS "site_photos: admins all"       ON public.site_photos;
DROP POLICY IF EXISTS "site_items: public read shown" ON public.site_items;
DROP POLICY IF EXISTS "site_items: admins all"        ON public.site_items;
CREATE POLICY "site_text: public read"        ON public.site_text   FOR SELECT USING (true);
CREATE POLICY "site_text: admins all"         ON public.site_text   FOR ALL USING (public.is_admin()) WITH CHECK (public.is_admin());
CREATE POLICY "site_photos: public read"      ON public.site_photos FOR SELECT USING (true);
CREATE POLICY "site_photos: admins all"       ON public.site_photos FOR ALL USING (public.is_admin()) WITH CHECK (public.is_admin());
CREATE POLICY "site_items: public read shown" ON public.site_items  FOR SELECT USING (active = true);
CREATE POLICY "site_items: admins all"        ON public.site_items  FOR ALL USING (public.is_admin()) WITH CHECK (public.is_admin());

-- Generated from src/data/siteLists.js (its `fallback` copies).
DO $seed$
DECLARE l text;
BEGIN
  CREATE TEMP TABLE seed_items (list text, slug text, data jsonb, sort_order int) ON COMMIT DROP;
  INSERT INTO seed_items (list, slug, data, sort_order) VALUES
      ('haircare', 'maria-nila', '{"name":"Maria Nila","name_fr":"","short_name":"","images":["/images/salon/maria-nila-heal.jpg"],"tagline":"Beautiful hair. Thoughtful choices. Exceptional performance.","tagline_fr":"De beaux cheveux. Des choix réfléchis. Une performance exceptionnelle.","body":"Maria Nila is a brand we are genuinely excited to have at Spa Rivier. We were first drawn to what the brand stands for — but the products themselves made us believers.\n\nWhat makes Maria Nila exceptional is the strength of the entire collection. Their shampoos and conditioners deliver beautiful results, while their styling products are equally impressive — something we find surprisingly rare in one complete haircare line.\n\nBeautifully formulated, beautifully presented and designed to perform, Maria Nila has quickly become one of our favourite professional haircare collections.","body_fr":"Maria Nila est une marque que nous sommes sincèrement enthousiastes d’offrir chez Spa Rivier. Ce sont d’abord les valeurs de la marque qui ont retenu notre attention — mais ce sont les produits eux-mêmes qui ont achevé de nous convaincre.\n\nCe qui rend Maria Nila exceptionnelle, c’est la force de toute sa collection. Ses shampooings et revitalisants donnent de magnifiques résultats, et ses produits coiffants sont tout aussi impressionnants — ce qui, selon nous, est étonnamment rare au sein d’une même gamme complète de soins capillaires.\n\nJoliment formulée, magnifiquement présentée et conçue pour donner des résultats, Maria Nila est rapidement devenue l’une de nos collections professionnelles de soins capillaires préférées.","lines":"","lines_fr":""}'::jsonb, 0),
      ('haircare', 'moroccanoil', '{"name":"Moroccanoil","name_fr":"","short_name":"","images":["/images/haircare/moroccanoil-1.webp","/images/haircare/moroccanoil-2.webp","/images/haircare/moroccanoil-3.webp","/images/haircare/moroccanoil-4.webp"],"tagline":"Argan oil. Iconic performance. Pure luxury.","tagline_fr":"L’huile d’argan. Une performance emblématique. Le luxe à l’état pur.","body":"Moroccanoil built its reputation around antioxidant-rich argan oil, an ingredient naturally rich in vitamins, essential fatty acids and nutrients that help nourish, soften and add beautiful shine to the hair.\n\nThis is a true luxury haircare collection, with products designed to leave hair feeling polished, healthy and beautifully manageable. It is also an especially strong choice for curly and textured hair, with nourishing formulas that help enhance softness, definition and control.\n\nAnd the luxury doesn’t stop with hair. Moroccanoil’s body collection brings that same signature feel and fragrance into beautifully indulgent body care.","body_fr":"Moroccanoil a bâti sa réputation autour de l’huile d’argan riche en antioxydants, un ingrédient naturellement riche en vitamines, en acides gras essentiels et en nutriments qui aident à nourrir et à adoucir les cheveux, tout en leur donnant une magnifique brillance.\n\nC’est une véritable collection de soins capillaires de luxe, avec des produits conçus pour laisser les cheveux soignés, en santé et merveilleusement faciles à coiffer. C’est aussi un choix particulièrement judicieux pour les cheveux bouclés et texturés, grâce à des formules nourrissantes qui rehaussent la douceur, la définition et le contrôle.\n\nEt le luxe ne s’arrête pas aux cheveux. La collection pour le corps de Moroccanoil apporte cette même sensation et ce même parfum signature à des soins corporels délicieusement réconfortants.","lines":"","lines_fr":""}'::jsonb, 1),
      ('haircare', 'joico', '{"name":"Joico","name_fr":"","short_name":"","images":["/images/salon/joico-k-pak.jpg","/images/salon/joico-youthlock.jpg","/images/haircare/joico-3.webp","/images/haircare/joico-4.webp","/images/haircare/joico-5.webp","/images/haircare/joico-6.webp","/images/haircare/joico-7.webp","/images/haircare/joico-8.webp"],"tagline":"Professional performance. Exceptional value. A true salon legacy.","tagline_fr":"Une performance professionnelle. Un rapport qualité-prix exceptionnel. Un véritable héritage de salon.","body":"Joico has earned its place as one of our favourite professional haircare brands because it does so many things well.\n\nThis is one of the most balanced legacy brands we carry — offering excellent value, an extensive selection of shampoos and conditioners, and some of the strongest styling products in our professional collection. Joico also brings award-winning scalp care to the table, making it a great choice for clients looking beyond beautiful hair to overall scalp and hair health.\n\nReliable, innovative and consistently high-performing, Joico has been trusted by stylists for decades — and it remains one of our personal favourites at Spa Rivier.","body_fr":"Joico s’est taillé une place parmi nos marques professionnelles de soins capillaires préférées parce qu’elle excelle dans tant de domaines.\n\nC’est l’une des marques de référence les plus équilibrées que nous proposons : un excellent rapport qualité-prix, un vaste choix de shampooings et de revitalisants, et certains des produits coiffants les plus performants de notre collection professionnelle. Joico propose aussi des soins du cuir chevelu primés, ce qui en fait un excellent choix pour qui recherche, au-delà de beaux cheveux, la santé globale du cuir chevelu et des cheveux.\n\nFiable, novatrice et toujours performante, Joico a la confiance des coiffeurs depuis des décennies — et elle demeure l’une de nos préférées chez Spa Rivier.","lines":"","lines_fr":""}'::jsonb, 2),
      ('haircare', 'redken', '{"name":"Redken","name_fr":"","short_name":"","images":["/images/haircare/redken-1.webp","/images/haircare/redken-2.webp","/images/haircare/redken-3.webp","/images/haircare/redken-4.webp","/images/haircare/redken-5.webp","/images/haircare/redken-6.webp","/images/haircare/redken-7.webp","/images/haircare/redken-8.webp"],"tagline":"Science-led haircare. Proven solutions. Trusted performance.","tagline_fr":"Des soins guidés par la science. Des solutions éprouvées. Une performance de confiance.","body":"Redken has built its reputation on a scientific, solution-focused approach to professional haircare.\n\nIts greatest strength is in its shampoos, conditioners and treatments, with targeted options for virtually every hair type and concern. Whether the goal is strength, moisture, repair, colour care, volume or scalp support, Redken offers a well-developed system designed to address specific needs.\n\nIt is a brand with a loyal following for good reason — dependable, professional and backed by decades of salon expertise.","body_fr":"Redken a bâti sa réputation sur une approche scientifique des soins capillaires professionnels, axée sur les solutions.\n\nSa plus grande force réside dans ses shampooings, revitalisants et traitements, avec des options ciblées pour pratiquement tous les types de cheveux et toutes les préoccupations. Qu’il s’agisse de force, d’hydratation, de réparation, de protection de la couleur, de volume ou de soin du cuir chevelu, Redken offre un système complet, conçu pour répondre à des besoins précis.\n\nC’est une marque qui compte une clientèle fidèle, et pour cause : fiable, professionnelle et appuyée par des décennies d’expertise en salon.","lines":"","lines_fr":""}'::jsonb, 3),
      ('haircare', 'ag-care', '{"name":"AG Care","name_fr":"","short_name":"","images":["/images/haircare/ag-care-1.webp"],"tagline":"Canadian made. Professional performance. Standout haircare.","tagline_fr":"Fabriqué au Canada. Une performance professionnelle. Des soins qui se démarquent.","body":"AG Care is one of our favourite Canadian haircare brands — proudly made right here in British Columbia.\n\nProduced in its own state-of-the-art facility, AG has earned a strong place in the professional haircare industry with beautifully formulated products that simply perform. The collection includes some true hero products — the kind our clients discover, love and come back for again and again.\n\nInnovative, dependable and distinctly its own, AG stands out in a very crowded world of professional haircare.\n\nAnd we have to admit, we love that one of our strongest professional brands is Canadian.","body_fr":"AG Care est l’une de nos marques canadiennes de soins capillaires préférées — fièrement fabriquée ici même, en Colombie-Britannique.\n\nProduite dans ses propres installations à la fine pointe de la technologie, AG s’est taillé une solide place dans l’industrie des soins capillaires professionnels grâce à des produits joliment formulés qui, tout simplement, donnent des résultats. La collection compte de véritables produits vedettes — ceux que notre clientèle découvre, adore et revient chercher encore et encore.\n\nNovatrice, fiable et résolument unique, AG se démarque dans l’univers très encombré des soins capillaires professionnels.\n\nEt nous devons l’avouer : nous adorons que l’une de nos meilleures marques professionnelles soit canadienne.","lines":"","lines_fr":""}'::jsonb, 4),
      ('haircare', 'design-me', '{"name":"Design.Me","name_fr":"","short_name":"","images":["/images/haircare/design-me-1.webp","/images/haircare/design-me-2.webp","/images/haircare/design-me-3.webp","/images/haircare/design-me-4.webp","/images/haircare/design-me-5.webp","/images/haircare/design-me-6.webp"],"tagline":"Canadian haircare with a little more personality.","tagline_fr":"Des soins capillaires canadiens, avec un brin de personnalité en plus.","body":"Design.Me is our second Canadian professional haircare brand, and it brings a fresh, fun energy to the department.\n\nThe collection is built around three easy-to-understand families: Gloss.Me for moisture and shine, Bounce.Me for curls, and Puff.Me for volume. Each category includes its own shampoos, conditioners, treatments and styling products, making it simple to build a complete routine around what your hair needs most.\n\nIt’s a smaller, focused line with playful packaging and a youthful personality — but the products are serious about performance.","body_fr":"Design.Me est notre deuxième marque canadienne de soins capillaires professionnels, et elle apporte une énergie fraîche et ludique au rayon.\n\nLa collection s’articule autour de trois familles faciles à comprendre : Gloss.Me pour l’hydratation et la brillance, Bounce.Me pour les boucles et Puff.Me pour le volume. Chaque famille comprend ses propres shampooings, revitalisants, traitements et produits coiffants, ce qui facilite la création d’une routine complète selon ce dont vos cheveux ont le plus besoin.\n\nC’est une gamme plus petite et ciblée, à l’emballage ludique et à la personnalité jeune — mais ses produits prennent la performance très au sérieux.","lines":"","lines_fr":""}'::jsonb, 5),
      ('haircare', 'sebastian', '{"name":"Sebastian","name_fr":"","short_name":"","images":["/images/haircare/sebastian-1.webp","/images/haircare/sebastian-2.webp","/images/haircare/sebastian-3.webp","/images/haircare/sebastian-4.webp","/images/haircare/sebastian-5.webp","/images/haircare/sebastian-6.webp"],"tagline":"Create. Re-create. Style without limits.","tagline_fr":"Créer. Recréer. Coiffer sans limites.","body":"Sebastian is a true legacy styling brand, built for women who see their hair as part of their personal style.\n\nIts strength is styling — products designed to help you create one look, then completely rework it into another. The collection is relatively focused, but within it are some true hero products that have earned a loyal following for their performance, versatility and staying power.\n\nSebastian speaks to the woman who loves beautiful hair, but also loves changing it up.","body_fr":"Sebastian est une véritable marque de référence en coiffage, conçue pour les femmes qui voient leurs cheveux comme une part de leur style personnel.\n\nSa force, c’est le coiffage : des produits conçus pour vous aider à créer un look, puis à le transformer complètement en un autre. La collection est relativement ciblée, mais elle compte de véritables produits vedettes qui ont gagné une clientèle fidèle grâce à leur performance, leur polyvalence et leur tenue.\n\nSebastian s’adresse à la femme qui aime les beaux cheveux, mais qui aime aussi changer de style.","lines":"","lines_fr":""}'::jsonb, 6),
      ('haircare', 'targeted', '{"name":"Targeted Hair Solutions","name_fr":"Solutions capillaires ciblées","short_name":"","images":[],"tagline":"Sometimes your hair needs more than everyday care.","tagline_fr":"Parfois, vos cheveux ont besoin de plus que des soins quotidiens.","body":"Our Targeted Hair Solutions collection brings together specialized professional products chosen to address specific hair and scalp concerns.\n\nFrom thinning hair and hard-water buildup to intensive repair, colour maintenance and instant problem-solving, these are the products we reach for when a more focused solution is needed.","body_fr":"Notre collection Solutions capillaires ciblées réunit des produits professionnels spécialisés, choisis pour répondre à des préoccupations précises des cheveux et du cuir chevelu.\n\nDes cheveux clairsemés et des dépôts d’eau calcaire à la réparation intensive, en passant par l’entretien de la couleur et les solutions instantanées, ce sont les produits vers lesquels nous nous tournons lorsqu’une solution plus ciblée s’impose.","lines":"Nioxin — thinning hair & scalp support\nK18 — intensive repair\nMalibu C — hard water & mineral buildup\nColor Wow — targeted, trend-forward problem solving\nCeleb Luxury — colour maintenance & enhancement","lines_fr":"Nioxin — cheveux clairsemés et soin du cuir chevelu\nK18 — réparation intensive\nMalibu C — eau calcaire et dépôts minéraux\nColor Wow — solutions ciblées et avant-gardistes\nCeleb Luxury — entretien et rehaussement de la couleur"}'::jsonb, 7),
      ('skincare', 'eminence', '{"name":"Eminence Organic Skin Care","name_fr":"","short_name":"Eminence","images":["/images/skincare/eminence-1.webp","/images/skincare/eminence-2.webp","/images/skincare/eminence-3.webp","/images/skincare/eminence-4.webp"],"tagline":"Trusted for 20 years. Loved from the very beginning.","tagline_fr":"Une confiance de 20 ans. Un coup de cœur depuis le premier jour.","body":"Eminence is one of those rare brands that has truly stood the test of time at Spa Rivier. We have carried it for 20 years, and we love it just as much today as we did when we first brought it in.\n\nKnown for its Hungarian roots, organic ingredients and B Corp certification, Eminence offers beautiful, effective skincare that is easy to understand and easy to use. It works just as well for someone beginning a skincare routine as it does for someone looking for more advanced, results-focused care.\n\nOver the years, many brands have come and gone. Eminence is different. It is trusted, dependable and wonderfully versatile — a brand we believe in completely and one we cannot imagine Spa Rivier without.","body_fr":"Eminence fait partie de ces rares marques qui ont véritablement résisté à l’épreuve du temps chez Spa Rivier. Nous la proposons depuis 20 ans, et nous l’aimons tout autant aujourd’hui qu’au jour où nous l’avons accueillie.\n\nReconnue pour ses racines hongroises, ses ingrédients biologiques et sa certification B Corp, Eminence offre des soins beaux et efficaces, faciles à comprendre et faciles à utiliser. Elle convient aussi bien à une personne qui commence sa routine de soins qu’à quelqu’un qui recherche des soins plus avancés, axés sur les résultats.\n\nAu fil des ans, bien des marques sont venues et reparties. Eminence est différente : fiable, constante et merveilleusement polyvalente, c’est une marque en laquelle nous croyons entièrement, et sans laquelle nous ne saurions imaginer Spa Rivier.","lines":"","lines_fr":""}'::jsonb, 0),
      ('skincare', 'noon', '{"name":"NOON Aesthetics","name_fr":"","short_name":"","images":["/images/skincare/noon-1.webp","/images/skincare/noon-2.webp","/images/skincare/noon-3.webp","/images/skincare/noon-4.webp","/images/skincare/noon-5.webp","/images/skincare/noon-6.webp"],"tagline":"Advanced skincare. Targeted results. Powerful, yet gentle.","tagline_fr":"Des soins avancés. Des résultats ciblés. Puissants, mais doux.","body":"NOON Aesthetics is the clinical skincare line we use when women are ready to take a more focused approach to their skin. Highly concentrated and results-driven, it is designed to target specific concerns with advanced formulations that feel sophisticated without being harsh.\n\nWe love NOON because it bridges the gap between powerful clinical skincare and everyday usability. It is ideal for women who want a more personalized, prescription-oriented approach to concerns such as aging, pigmentation, texture and overall skin quality.\n\nFor the woman who is serious about her skin and wants to age later, age better, NOON is a true game changer.","body_fr":"NOON Aesthetics est la gamme de soins cliniques que nous utilisons lorsque les femmes sont prêtes à adopter une approche plus ciblée pour leur peau. Hautement concentrée et axée sur les résultats, elle cible des préoccupations précises grâce à des formules avancées, raffinées sans être agressives.\n\nNous aimons NOON parce qu’elle fait le pont entre des soins cliniques puissants et une utilisation au quotidien. Elle est idéale pour les femmes qui souhaitent une approche plus personnalisée, inspirée des soins sur ordonnance, pour des préoccupations comme le vieillissement, la pigmentation, la texture et la qualité globale de la peau.\n\nPour la femme qui prend sa peau au sérieux et souhaite vieillir plus tard et vieillir mieux, NOON change véritablement la donne.","lines":"","lines_fr":""}'::jsonb, 1),
      ('skincare', 'jane-iredale', '{"name":"Jane Iredale","name_fr":"","short_name":"","images":["/images/skincare/jane-iredale-1.webp","/images/skincare/jane-iredale-2.webp"],"tagline":"Makeup that cares for your skin.","tagline_fr":"Un maquillage qui prend soin de votre peau.","body":"Jane Iredale is where skincare and makeup truly come together. Known for beautiful mineral formulas, healthy-looking coverage and easy application, it gives you the freedom to choose everything from a light, natural finish to fuller coverage — without feeling heavy on the skin.\n\nWe love Jane Iredale because it does more than make skin look beautiful. Many of its complexion products also offer broad-spectrum mineral SPF protection, with several recommended by The Skin Cancer Foundation.\n\nWith foundations, powders, blushes, eye colour, lip products and more, it is a wonderfully complete makeup collection that is simple to use and easy to love. For many of our clients, once they experience how Jane Iredale looks and feels on their skin, it becomes very hard to go back.","body_fr":"Avec Jane Iredale, les soins de la peau et le maquillage se rejoignent vraiment. Reconnue pour ses magnifiques formules minérales, sa couvrance d’apparence saine et son application facile, la marque vous laisse choisir d’un fini léger et naturel jusqu’à une couvrance plus complète — sans jamais alourdir la peau.\n\nNous aimons Jane Iredale parce qu’elle fait plus qu’embellir la peau. Bon nombre de ses produits pour le teint offrent aussi une protection solaire minérale à large spectre, et plusieurs sont recommandés par The Skin Cancer Foundation.\n\nFonds de teint, poudres, fards à joues, couleurs pour les yeux, produits pour les lèvres et plus encore : c’est une collection de maquillage merveilleusement complète, simple à utiliser et facile à aimer. Pour bon nombre de nos clientes, une fois qu’elles ont découvert l’effet et le confort de Jane Iredale sur leur peau, il devient très difficile de revenir en arrière.","lines":"","lines_fr":""}'::jsonb, 2),
      ('bathbody', 'toasted-crumpet', '{"name":"Toasted Crumpet","name_fr":"","short_name":"","images":["/images/bathbody/toasted-crumpet-1.webp","/images/bathbody/toasted-crumpet-2.webp","/images/bathbody/toasted-crumpet-3.webp"],"tagline":"British charm, inspired by nature","tagline_fr":"Le charme britannique, inspiré par la nature","body":"Discover the beauty of the British countryside with Toasted Crumpet, a charming collection of bath and body essentials proudly made in Britain.\n\nKnown for its exquisite hand-painted botanical designs, Toasted Crumpet brings together beautiful fragrances, luxurious hand creams, and richly moisturizing soaps. Every product feels like a little indulgence, combining everyday practicality with thoughtful presentation.\n\nAt Spa Rivier, we love how Toasted Crumpet turns simple moments of self-care into something special. Beautiful to use and equally lovely to give.","body_fr":"Découvrez la beauté de la campagne anglaise avec Toasted Crumpet, une charmante collection d’essentiels pour le bain et le corps fièrement fabriqués en Grande-Bretagne.\n\nReconnue pour ses exquis motifs botaniques peints à la main, Toasted Crumpet réunit de beaux parfums, des crèmes pour les mains luxueuses et des savons richement hydratants. Chaque produit est un petit plaisir, qui allie le côté pratique du quotidien à une présentation soignée.\n\nChez Spa Rivier, nous aimons la façon dont Toasted Crumpet transforme les simples moments de soin en quelque chose de spécial. Un bonheur à utiliser, et tout aussi charmant à offrir.","lines":"","lines_fr":""}'::jsonb, 0),
      ('bathbody', 'library-of-flowers', '{"name":"Library of Flowers","name_fr":"","short_name":"","images":["/images/bathbody/library-of-flowers-1.webp","/images/bathbody/library-of-flowers-2.webp","/images/bathbody/library-of-flowers-3.webp","/images/bathbody/library-of-flowers-4.webp","/images/bathbody/library-of-flowers-5.webp"],"tagline":"A little luxury, inspired by the garden","tagline_fr":"Un petit luxe, inspiré du jardin","body":"Step into a garden of beautiful fragrances with Library of Flowers, a delightful collection created by Margot Elena.\n\nInspired by nature’s most captivating scents, this collection features beautiful perfumes, luxurious hand creams, and indulgent bath and body products. Each fragrance is thoughtfully layered, creating a sensory experience that feels both familiar and wonderfully special.\n\nAt Spa Rivier, we love Library of Flowers for its feminine charm, beautiful packaging, and timeless appeal. A lovely way to treat yourself or someone special.","body_fr":"Entrez dans un jardin de parfums magnifiques avec Library of Flowers, une ravissante collection créée par Margot Elena.\n\nInspirée des senteurs les plus envoûtantes de la nature, cette collection propose de beaux parfums, des crèmes pour les mains luxueuses et de délicieux produits pour le bain et le corps. Chaque fragrance est composée avec soin, par couches, pour créer une expérience sensorielle à la fois familière et merveilleusement spéciale.\n\nChez Spa Rivier, nous aimons Library of Flowers pour son charme féminin, ses magnifiques emballages et son attrait intemporel. Une jolie façon de vous gâter ou de gâter une personne qui vous est chère.","lines":"","lines_fr":""}'::jsonb, 1),
      ('bathbody', 'cottage-greenhouse', '{"name":"The Cottage Greenhouse","name_fr":"","short_name":"","images":["/images/bathbody/cottage-greenhouse-1.webp","/images/bathbody/cottage-greenhouse-2.webp","/images/bathbody/cottage-greenhouse-3.webp","/images/bathbody/cottage-greenhouse-4.webp","/images/bathbody/cottage-greenhouse-5.webp"],"tagline":"Garden-inspired goodness for everyday self-care","tagline_fr":"Les bienfaits du jardin pour vos soins de tous les jours","body":"Inspired by the beauty and goodness of nature, The Cottage Greenhouse is a delightful bath and body collection created by Margot Elena.\n\nCombining botanical-inspired ingredients with beautiful fragrances, the collection offers nourishing body butters, rich hand creams, refreshing body washes, and indulgent treatments for hands, feet, and body. Each collection brings a fresh approach to everyday self-care.\n\nAt Spa Rivier, we love The Cottage Greenhouse for its garden-inspired simplicity, beautiful presentation, and wonderfully nourishing products. A little everyday luxury, inspired by nature.","body_fr":"Inspirée par la beauté et les bienfaits de la nature, The Cottage Greenhouse est une ravissante collection pour le bain et le corps créée par Margot Elena.\n\nAlliant des ingrédients d’inspiration botanique à de beaux parfums, la collection propose des beurres corporels nourrissants, de riches crèmes pour les mains, des nettoyants pour le corps rafraîchissants et des soins gourmands pour les mains, les pieds et le corps. Chaque collection apporte un vent de fraîcheur à vos soins de tous les jours.\n\nChez Spa Rivier, nous aimons The Cottage Greenhouse pour sa simplicité inspirée du jardin, sa belle présentation et ses produits merveilleusement nourrissants. Un petit luxe au quotidien, inspiré par la nature.","lines":"","lines_fr":""}'::jsonb, 2),
      ('bathbody', 'tokyomilk', '{"name":"TokyoMilk","name_fr":"","short_name":"","images":["/images/bathbody/tokyomilk-1.webp","/images/bathbody/tokyomilk-2.webp","/images/bathbody/tokyomilk-3.webp","/images/bathbody/tokyomilk-4.webp","/images/bathbody/tokyomilk-5.webp","/images/bathbody/tokyomilk-6.webp","/images/bathbody/tokyomilk-7.webp","/images/bathbody/tokyomilk-8.webp","/images/bathbody/tokyomilk-9.webp"],"tagline":"Fragrance with an unexpected twist","tagline_fr":"Des parfums qui sortent de l’ordinaire","body":"For those who appreciate something a little different, TokyoMilk is a world of intriguing fragrances, artistic expression, and unexpected combinations.\n\nCreated by Margot Elena, TokyoMilk blends distinctive scent combinations with imaginative packaging and a touch of mystery. From captivating perfumes to luxurious hand creams, every product invites you to express your individuality.\n\nAt Spa Rivier, we love TokyoMilk for its originality and personality. It’s a collection for women who enjoy discovering something beautiful, unexpected, and uniquely their own.","body_fr":"Pour celles et ceux qui aiment ce qui sort un peu de l’ordinaire, TokyoMilk est un univers de parfums intrigants, d’expression artistique et d’associations inattendues.\n\nCréée par Margot Elena, TokyoMilk marie des accords olfactifs singuliers à des emballages pleins d’imagination et à une touche de mystère. Des parfums envoûtants aux crèmes pour les mains luxueuses, chaque produit vous invite à exprimer votre personnalité.\n\nChez Spa Rivier, nous aimons TokyoMilk pour son originalité et sa personnalité. C’est une collection pour les femmes qui aiment découvrir quelque chose de beau, d’inattendu et d’unique, à leur image.","lines":"","lines_fr":""}'::jsonb, 3),
      ('bathbody', 'moroccanoil-body', '{"name":"Moroccanoil Body","name_fr":"","short_name":"","images":["/images/bathbody/moroccanoil-body-1.webp"],"tagline":"Luxurious care, from head to toe","tagline_fr":"Des soins luxueux, de la tête aux pieds","body":"Bring the luxury of Moroccanoil into your everyday body care routine with a beautiful collection inspired by the nourishing benefits of argan oil.\n\nFrom moisturizing body lotions and hand creams to refreshing shower gels and fragrant body oils, Moroccanoil Body combines effective care with beautiful textures and captivating fragrances.\n\nAt Spa Rivier, we’ve long appreciated Moroccanoil for its quality and performance. The Body Collection brings that same experience beyond haircare, making everyday moments feel a little more luxurious.","body_fr":"Intégrez le luxe de Moroccanoil à votre routine de soins corporels avec une magnifique collection inspirée des bienfaits nourrissants de l’huile d’argan.\n\nDes lotions hydratantes pour le corps et des crèmes pour les mains aux gels douche rafraîchissants et aux huiles parfumées pour le corps, Moroccanoil Body allie des soins efficaces à de belles textures et à des parfums envoûtants.\n\nChez Spa Rivier, nous apprécions depuis longtemps Moroccanoil pour sa qualité et sa performance. La collection pour le corps prolonge cette même expérience au-delà des soins capillaires, pour rendre les moments du quotidien un peu plus luxueux.","lines":"","lines_fr":""}'::jsonb, 4),
      ('bathbody', 'well-kept', '{"name":"Well Kept","name_fr":"","short_name":"","images":["/images/bathbody/well-kept-1.webp","/images/bathbody/well-kept-2.webp","/images/bathbody/well-kept-3.webp","/images/bathbody/well-kept-4.webp"],"tagline":"Thoughtful self-care, made in Canada","tagline_fr":"Des soins bien pensés, fabriqués au Canada","body":"Beautifully simple and thoughtfully designed, Well Kept is a Canadian brand bringing a fresh perspective to everyday personal care.\n\nWith an emphasis on sustainability, quality ingredients, and products made to last, Well Kept offers beautifully crafted shaving essentials, bath products, and personal care accessories. Their reusable safety razors are a wonderful alternative to disposable plastic, combining practical design with a more mindful approach to self-care.\n\nAt Spa Rivier, we appreciate Canadian brands that make thoughtful choices without compromising quality. Well Kept reminds us that caring for ourselves and our environment can go hand in hand.","body_fr":"Merveilleusement simple et conçue avec soin, Well Kept est une marque canadienne qui pose un regard neuf sur les soins personnels de tous les jours.\n\nMisant sur la durabilité, des ingrédients de qualité et des produits faits pour durer, Well Kept propose des essentiels de rasage magnifiquement conçus, des produits pour le bain et des accessoires de soins personnels. Ses rasoirs de sûreté réutilisables sont une merveilleuse solution de rechange au plastique jetable, alliant un design pratique à une approche plus consciente des soins.\n\nChez Spa Rivier, nous apprécions les marques canadiennes qui font des choix réfléchis sans compromis sur la qualité. Well Kept nous rappelle que prendre soin de soi et de l’environnement peut aller de pair.","lines":"","lines_fr":""}'::jsonb, 5),
      ('bathbody', 'hempz', '{"name":"Hempz","name_fr":"","short_name":"","images":["/images/bathbody/hempz-1.webp","/images/bathbody/hempz-2.webp","/images/bathbody/hempz-3.webp","/images/bathbody/hempz-4.webp","/images/bathbody/hempz-5.webp"],"tagline":"Everyday hydration that feels wonderful","tagline_fr":"Une hydratation quotidienne qui fait du bien","body":"Healthy-looking, beautifully moisturized skin starts with everyday care, and Hempz makes it easy to enjoy.\n\nKnown for its nourishing, hemp seed oil-enriched body moisturizers, Hempz combines effective hydration with an irresistible collection of fragrances. From fresh and fruity to warm and comforting, there’s something to suit every preference.\n\nAt Spa Rivier, we love Hempz for its dependable everyday moisturizing care, generous selection, and approachable price point. A simple pleasure that makes caring for your skin feel wonderful.","body_fr":"Une peau éclatante de santé et magnifiquement hydratée commence par des soins de tous les jours, et Hempz les rend faciles à apprécier.\n\nReconnue pour ses hydratants pour le corps nourrissants, enrichis d’huile de graines de chanvre, Hempz allie une hydratation efficace à une irrésistible collection de parfums. Du frais et fruité au chaleureux et réconfortant, il y en a pour tous les goûts.\n\nChez Spa Rivier, nous aimons Hempz pour ses soins hydratants fiables au quotidien, son vaste choix et ses prix accessibles. Un plaisir simple qui fait de chaque soin de la peau un moment merveilleux.","lines":"","lines_fr":""}'::jsonb, 6),
      ('bathbody_accessories', 'lavoh', '{"name":"Lavoh Cloths","name_fr":"","short_name":"","images":["/images/bathbody/lavoh-1.webp"],"tagline":"A thoughtful addition to your daily routine","tagline_fr":"Un ajout bien pensé à votre routine quotidienne","body":"Sometimes the simplest accessories make the biggest difference in our everyday routines.\n\nLavoh cloths bring a practical touch to personal care, offering a convenient addition to your cleansing and bathing essentials.\n\nAt Spa Rivier, we believe that thoughtful details can make even the simplest daily rituals more enjoyable.","body_fr":"Ce sont parfois les accessoires les plus simples qui font la plus grande différence dans nos routines de tous les jours.\n\nLes chiffons Lavoh apportent une touche pratique aux soins personnels et complètent commodément vos essentiels pour le nettoyage et le bain.\n\nChez Spa Rivier, nous croyons que des détails bien pensés peuvent rendre plus agréables même les plus simples rituels quotidiens.","lines":"","lines_fr":""}'::jsonb, 0),
      ('bathbody_accessories', 'honeylux', '{"name":"HoneyLux Silk","name_fr":"","short_name":"","images":["/images/bathbody/honeylux-1.webp","/images/bathbody/honeylux-2.webp","/images/bathbody/honeylux-3.webp","/images/bathbody/honeylux-4.webp","/images/bathbody/honeylux-5.webp","/images/bathbody/honeylux-6.webp","/images/bathbody/honeylux-7.webp"],"tagline":"A touch of luxury for your hair and skin","tagline_fr":"Une touche de luxe pour vos cheveux et votre peau","body":"Experience the beautiful simplicity of silk with HoneyLux, a Canadian brand dedicated to luxurious, thoughtfully designed beauty accessories.\n\nFeaturing premium organic mulberry silk, the collection includes pillowcases, sleep masks, and hair accessories designed to be gentle on your skin and hair. Silk’s naturally smooth surface helps reduce friction, making it a lovely addition to your nighttime beauty routine.\n\nAt Spa Rivier, we appreciate products that combine everyday function with a little luxury. HoneyLux offers beautiful finishing touches for your personal care routine and thoughtful gifts for someone special.","body_fr":"Découvrez la belle simplicité de la soie avec HoneyLux, une marque canadienne qui se consacre à des accessoires beauté luxueux et pensés avec soin.\n\nConfectionnée en soie de mûrier biologique de première qualité, la collection comprend des taies d’oreiller, des masques de sommeil et des accessoires pour cheveux conçus pour être doux pour la peau et les cheveux. La surface naturellement lisse de la soie aide à réduire la friction, ce qui en fait un charmant ajout à votre routine beauté du soir.\n\nChez Spa Rivier, nous apprécions les produits qui allient l’utilité au quotidien à une petite touche de luxe. HoneyLux offre de belles touches finales pour votre routine de soins et des cadeaux attentionnés pour une personne qui vous est chère.","lines":"","lines_fr":""}'::jsonb, 1),
      ('team', 'donna', '{"name":"Donna","title":"Founder & Owner","title_fr":"Fondatrice & Propriétaire","image":"/images/team/donna.jpg","image_alt":"Donna in the Spa Rivier boutique, holding her nomination for the 2025 Lifetime Achievement Business Award","image_alt_fr":"Donna dans la boutique Spa Rivier, tenant sa nomination au Prix d''affaires pour l''ensemble des réalisations 2025","bio":"With over 40 years in the beauty and wellness industry, Donna has built something remarkable: a world-class destination in the heart of British Columbia''s Cariboo region. A hairstylist by trade, an aromatherapy specialist by passion, and a visionary by nature, Donna has never stopped bringing the finest ideas from across the continent back home to Quesnel. Honoured three times as Quesnel''s Business Person of the Year (1998, 2010, 2018) and awarded Retailer of the Year (2008).","bio_fr":"Avec plus de 40 ans d''expérience dans l''industrie de la beauté et du bien-être, Donna a créé une destination remarquable au cœur de la région Cariboo, en Colombie-Britannique. Coiffeuse de métier, spécialiste en aromathérapie par passion et visionnaire de nature, Donna n''a jamais cessé de rapporter à Quesnel les meilleures idées de tout le continent. Elle a été nommée trois fois Personnalité d''affaires de l''année à Quesnel (1998, 2010, 2018) et a reçu le prix de Détaillante de l''année (2008).","quote":"\"I believe Quesnel deserves the best. And Spa Rivier is my promise to deliver it — every single day.\"","quote_fr":"« Je crois que Quesnel mérite le meilleur. Et Spa Rivier est ma promesse de le lui offrir — chaque jour. »"}'::jsonb, 0),
      ('spa_faq', 'faq-1', '{"q":"Where are you located?","q_fr":"","a":"Spa Rivier is located at 353 Reid Street, Downtown Quesnel, BC — in the heart of the Cariboo region.","a_fr":""}'::jsonb, 0),
      ('spa_faq', 'faq-2', '{"q":"Do you accommodate wedding parties?","q_fr":"","a":"Wedding parties are warmly welcomed at Spa Rivier. We strongly recommend booking your wedding date as early as possible — 4–6 weeks or more in advance. Customary services for bridal parties include manicures, pedicures, waxing, and perfect hairstyling.","a_fr":""}'::jsonb, 1),
      ('spa_faq', 'faq-3', '{"q":"How do I book a spa package or service?","q_fr":"","a":"Simply call us at 250-992-8084 and one of our Guest Managers will guide you to the perfect experience. You can also book online anytime at sparivier.ca.","a_fr":""}'::jsonb, 2),
      ('spa_faq', 'faq-4', '{"q":"Is there a deposit required to book a package?","q_fr":"","a":"We require a credit card to confirm your reservation. We ask the courtesy of 72-hour cancellation notice for all spa packages and group bookings, and 24 hours for individual services. Missed appointments will be charged 50% of the treatment cost.","a_fr":""}'::jsonb, 3),
      ('spa_faq', 'faq-5', '{"q":"How far in advance should I book?","q_fr":"","a":"Some days are more popular than others. We recommend booking as soon as your plans are made — 4–6 weeks is ideal for packages and special occasions. Walk-ins are always welcome.","a_fr":""}'::jsonb, 4),
      ('spa_faq', 'faq-6', '{"q":"Do your prices include tax?","q_fr":"","a":"All prices are quoted in Canadian dollars. Taxes, where applicable, are additional.","a_fr":""}'::jsonb, 5),
      ('spa_faq', 'faq-7', '{"q":"What forms of payment do you accept?","q_fr":"","a":"We accept Visa, MasterCard, Interac Payment, and Cash. US currency is accepted at par.","a_fr":""}'::jsonb, 6),
      ('spa_faq', 'faq-8', '{"q":"What is your policy for late arrivals?","q_fr":"","a":"Late arrivals may require us to reduce the length of treatment while applying full charges, to ensure subsequent guests are not affected. Please call us at 250-992-8084 if you are running late.","a_fr":""}'::jsonb, 7),
      ('spa_faq', 'faq-9', '{"q":"Are children welcome in the spa?","q_fr":"","a":"Spa Rivier Spa is a sanctuary for adults. For the comfort of all guests, we ask that children not be brought into the spa area. All spa clients must be at least 16 years of age, or accompanied by an adult.","a_fr":""}'::jsonb, 8),
      ('articles', 'science-behind-oxygeneo', '{"title":"The Science Behind OxyGeneo® — Why Your Skin Needs Oxygen","title_fr":"La science derrière OxyGeneo® : pourquoi votre peau a besoin d’oxygène","category":"MediSpa","category_fr":"MédiSpa","image":"/images/medispa/oxygeneo-treatment.jpg","featured":true,"date":"May 20, 2026","date_fr":"20 mai 2026","read_time":"4 min read","read_time_fr":"4 min de lecture","author":"The Spa Rivier MediSpa Team","author_fr":"L’équipe MédiSpa Spa Rivier","excerpt":"Discover how Spa Rivier''s signature OxyGeneo treatment uses patented OxyPod technology to exfoliate, oxygenate, and infuse your skin in a single luxurious session.","excerpt_fr":"Découvrez comment le soin OxyGeneo signature de Spa Rivier utilise la technologie brevetée OxyPod pour exfolier, oxygéner et infuser votre peau en une seule séance luxueuse.","body":"Your skin breathes. Not in the literal sense — but at the cellular level, oxygen is the engine behind every repair, renewal, and radiance-boosting process your complexion performs. And yet, modern life — stress, pollution, screen time, and age — steadily depletes the oxygen your skin cells receive.\n\nThat''s the problem OxyGeneo® was designed to solve. Available exclusively at our Spa Rivier MediSpa, OxyGeneo® is the world''s first OxyPod technology — a three-in-one treatment that simultaneously exfoliates the uppermost skin layer, stimulates oxygenation from within, and infuses active ingredients at the optimal moment of cellular receptivity.\n\n## How Does It Actually Work?\n\nThe OxyGeneo handpiece glides over your skin while the OxyPod capsule reacts with a proprietary gel to create a gentle CO₂ bubble-burst effect on the skin''s surface. Your body, detecting this localized CO₂ increase, responds by rushing oxygen-rich blood to the area — a natural physiological process called the Bohr Effect. The result: deep, internal oxygenation without any external oxygen application.\n\nSimultaneously, the treatment infuses concentrated active serums — vitamin C, hyaluronic acid, retinol, or brightening complexes — into the freshly oxygenated, maximally receptive skin. Ingredient absorption at this moment is significantly higher than in any traditional facial.\n\n## What Results Can You Expect?\n\nAfter a single 60-minute session, most clients notice an immediate brightening and smoothing effect — often described as a \"lit from within\" glow. With a course of treatments, OxyGeneo delivers measurable improvements in fine lines, hyperpigmentation, skin texture, and firmness.\n\nThere is zero downtime. You can return to your day immediately — and we find most clients arrive for their treatment on a lunch break. Our Spa Rivier MediSpa specialists will recommend the right OxyPod formula for your skin type and concern during your complimentary consultation.\n\n[Book Your OxyGeneo Consultation](/medispa)","body_fr":"Votre peau respire. Pas au sens littéral, mais au niveau cellulaire : l’oxygène est le moteur de chaque processus de réparation, de renouvellement et d’éclat. Pourtant, le stress, la pollution, les écrans et l’âge réduisent progressivement l’oxygène reçu par vos cellules cutanées.\n\nC’est le problème qu’OxyGeneo® a été conçu pour résoudre. Offert exclusivement dans notre MédiSpa Spa Rivier, OxyGeneo® est la première technologie OxyPod au monde : un soin trois-en-un qui exfolie la couche superficielle, stimule l’oxygénation de l’intérieur et infuse des actifs au moment idéal de réceptivité cellulaire.\n\n## Comment fonctionne-t-il vraiment ?\n\nLa pièce à main OxyGeneo glisse sur votre peau tandis que la capsule OxyPod réagit avec un gel breveté pour créer un doux effet de bulles de CO₂ à la surface. Votre corps réagit à cette hausse localisée en dirigeant un sang riche en oxygène vers la zone : c’est l’effet Bohr. Le résultat : une oxygénation profonde et interne, sans application d’oxygène externe.\n\nLe soin infuse simultanément des sérums concentrés — vitamine C, acide hyaluronique, rétinol ou complexes éclaircissants — dans une peau fraîchement oxygénée et particulièrement réceptive. L’absorption des actifs est alors nettement supérieure à celle d’un soin du visage traditionnel.\n\n## Quels résultats pouvez-vous attendre ?\n\nAprès une seule séance de 60 minutes, la plupart des clientes constatent immédiatement un teint plus lumineux et une peau plus lisse, souvent décrits comme un éclat « venu de l’intérieur ». Une cure améliore visiblement les ridules, l’hyperpigmentation, la texture et la fermeté.\n\nAucun temps de récupération n’est nécessaire. Vous pouvez reprendre votre journée immédiatement. Nos spécialistes du MédiSpa Spa Rivier vous recommanderont la formule OxyPod adaptée à votre type de peau et à vos préoccupations lors de votre consultation gratuite.\n\n[Réserver une consultation OxyGeneo](/medispa)"}'::jsonb, 0),
      ('articles', 'spring-skincare-reset', '{"title":"Spring Skincare Reset: The 5 Treatments Your Skin Needs Right Now","title_fr":"Réinitialiser sa peau au printemps : les 5 soins dont votre teint a besoin","category":"Skincare","category_fr":"Soins de la peau","image":"/images/medispa/eminence-strawberry-rhubarb.jpg","featured":false,"date":"May 12, 2026","date_fr":"12 mai 2026","read_time":"5 min read","read_time_fr":"5 min de lecture","author":"Spa Rivier Spa Team","author_fr":"L’équipe Spa Spa Rivier","excerpt":"Winter takes a toll. As the season shifts, here are the Spa Rivier spa and MediSpa treatments that will restore radiance, hydration, and evenness to your complexion.","excerpt_fr":"L’hiver laisse des traces. À l’arrivée de la nouvelle saison, découvrez les soins du Spa et du MédiSpa Spa Rivier qui restaureront l’éclat, l’hydratation et l’uniformité de votre teint.","body":"After months of cold air, indoor heating, and reduced UV protection, your skin in spring is often dull, dehydrated, and uneven. This is the season to reset — and there''s no better place to do it than at Spa Rivier.\n\n## 1. The Brightening Peel\n\nOur clinical brightening peel uses a vitamin C complex to dissolve the layer of dead, winter-dulled cells and reveal the luminous skin beneath. A series of three sessions, spaced two weeks apart, produces dramatic, lasting clarity.\n\n## 2. Eminence Organic Facial — Strawberry Rhubarb Hyaluronic Collection\n\nThe seasonal favourite at our spa. Packed with fruit enzymes and hyaluronic complex, this facial delivers deep hydration while gently brightening — perfect for transitioning skin that has lost its winter moisture barrier.\n\n## 3. OxyGeneo Oxygenation Treatment\n\nSpring is the ideal time for an OxyGeneo boost. Paired with a vitamin C OxyPod, this treatment counteracts months of oxidative stress and delivers a week-visible brightening result.\n\n## 4. Micro-Needling for Texture & Tone\n\nIf winter left your skin with rough patches, enlarged pores, or residual breakout marks, a micro-needling session with DermaRoller resets the canvas. Collagen stimulation begins within 48 hours and continues for weeks.\n\n## 5. Lash Lift & Brow Lamination\n\nSpring is the season of low-maintenance glamour. A lash lift and brow lamination at Spa Rivier takes 90 minutes and gives you six weeks of effortless, wide-awake beauty — no mascara required.\n\n[Book a Spring Treatment](/spa)","body_fr":"Après des mois d’air froid, de chauffage intérieur et de protection UV réduite, votre peau est souvent terne, déshydratée et irrégulière au printemps. C’est le moment idéal pour repartir sur de bonnes bases, et il n’y a pas de meilleur endroit que Spa Rivier.\n\n## 1. Le peeling éclaircissant\n\nNotre peeling clinique éclaircissant utilise un complexe de vitamine C pour éliminer la couche de cellules mortes ternies par l’hiver et révéler la luminosité sous-jacente. Une série de trois séances espacées de deux semaines produit une clarté spectaculaire et durable.\n\n## 2. Soin du visage biologique Eminence — collection fraise-rhubarbe et acide hyaluronique\n\nLe favori saisonnier de notre spa. Riche en enzymes de fruits et en complexe hyaluronique, ce soin hydrate en profondeur tout en éclaircissant doucement, idéal pour une peau qui sort de l’hiver.\n\n## 3. Soin d’oxygénation OxyGeneo\n\nLe printemps est le moment parfait pour offrir un regain d’énergie à votre peau avec OxyGeneo. Associé à un OxyPod à la vitamine C, ce soin compense des mois de stress oxydatif et révèle un teint plus lumineux pendant une semaine.\n\n## 4. Micro-needling pour la texture et le teint\n\nSi l’hiver a laissé des zones rugueuses, des pores dilatés ou des marques résiduelles, une séance de micro-needling avec DermaRoller réinitialise votre peau. La stimulation du collagène commence dans les 48 heures et se poursuit pendant plusieurs semaines.\n\n## 5. Rehaussement de cils et laminage des sourcils\n\nLe printemps est la saison d’un glamour facile à entretenir. Un rehaussement de cils et un laminage des sourcils chez Spa Rivier prennent 90 minutes et offrent six semaines de beauté éveillée sans effort, sans mascara.\n\n[Réserver un soin printanier](/spa)"}'::jsonb, 1),
      ('articles', 'guide-to-spa-etiquette', '{"title":"First-Time Guest? Your Complete Guide to Spa Etiquette at Spa Rivier","title_fr":"Première visite ? Le guide complet de l’étiquette du spa chez Spa Rivier","category":"Wellness","category_fr":"Bien-être","image":"/images/spa/bath-ritual.jpg","featured":false,"date":"April 28, 2026","date_fr":"28 avril 2026","read_time":"3 min read","read_time_fr":"3 min de lecture","author":"Spa Rivier Guest Relations","author_fr":"Relations invitées Spa Rivier","excerpt":"Everything you need to know before your first visit — from arrival time and what to wear, to tipping, silence, and how to make the absolute most of your experience.","excerpt_fr":"Tout ce qu’il faut savoir avant votre première visite : heure d’arrivée, tenue, pourboires, silence et conseils pour profiter pleinement de votre expérience.","body":"Your first spa visit should feel like a relief — not a source of anxiety. We want you to arrive knowing exactly what to expect, so the moment you step through our doors, you can simply let go.\n\n## Arrive 15 Minutes Early\n\nWe ask all first-time guests to arrive 15 minutes before their appointment. This allows time to complete your wellness consultation form, change, and begin the transition into a deeply relaxed state. Arriving rushed disrupts the experience for you and our practitioners.\n\n## What to Wear (and Leave at Home)\n\nJewellery, fragrance, and heavy makeup should be left at home — or removed on arrival. We provide robes, slippers, and all necessary linens. Your skin should be bare and clean for most treatments to work optimally.\n\n## Communication is Everything\n\nBefore your treatment begins, your therapist will ask about pressure preferences, any areas to avoid, and your goals for the session. Please be honest. If something feels uncomfortable during the treatment, speak up immediately — your comfort is always the priority.\n\n## The Quiet Zone\n\nSpa Rivier maintains a tranquil environment throughout the spa. Phone calls should be taken outside, and voices kept low. This courtesy extends to other guests who are in states of deep relaxation.\n\n## Gratuities\n\nGratuities are always appreciated and never expected. If your therapist, aesthetician, or stylist has made your day extraordinary, 15–20% is a meaningful expression of gratitude.\n\n[Book Your First Visit](/spa)","body_fr":"Votre première visite au spa devrait être un soulagement, jamais une source d’anxiété. Nous voulons que vous sachiez exactement à quoi vous attendre afin que, dès votre arrivée, vous puissiez simplement lâcher prise.\n\n## Arrivez 15 minutes à l’avance\n\nNous demandons à toutes les nouvelles clientes d’arriver 15 minutes avant leur rendez-vous. Cela laisse le temps de remplir le formulaire de consultation, de vous changer et d’entrer progressivement dans un état de profonde détente. Une arrivée précipitée perturbe votre expérience et celle de nos praticiennes.\n\n## Que porter et que laisser à la maison\n\nLaissez les bijoux, le parfum et le maquillage prononcé à la maison, ou retirez-les à votre arrivée. Nous fournissons peignoirs, chaussons et linge nécessaire. Pour la plupart des soins, votre peau doit être propre et démaquillée.\n\n## La communication est essentielle\n\nAvant le soin, votre thérapeute vous demandera vos préférences de pression, les zones à éviter et vos objectifs. Soyez honnête. Si quelque chose est inconfortable, dites-le immédiatement : votre confort est toujours prioritaire.\n\n## La zone de calme\n\nSpa Rivier maintient une atmosphère paisible dans tout le spa. Les appels doivent être pris à l’extérieur et les voix rester douces, par respect pour les autres clientes en pleine détente.\n\n## Pourboires\n\nLes pourboires sont toujours appréciés, jamais obligatoires. Si votre thérapeute, esthéticienne ou styliste a rendu votre journée extraordinaire, 15 à 20 % est une belle façon d’exprimer votre gratitude.\n\n[Réserver votre première visite](/spa)"}'::jsonb, 2),
      ('articles', 'micro-needling-explained', '{"title":"Micro-Needling Explained: What It Is, What It Does, and Who It''s For","title_fr":"Le micro-needling expliqué : fonctionnement, résultats et personnes concernées","category":"MediSpa","category_fr":"MédiSpa","image":"/images/medispa/micro-needling-before-after.jpg","featured":false,"date":"April 14, 2026","date_fr":"14 avril 2026","read_time":"6 min read","read_time_fr":"6 min de lecture","author":"The Spa Rivier MediSpa Team","author_fr":"L’équipe MédiSpa Spa Rivier","excerpt":"One of our most requested MediSpa treatments — micro-needling stimulates your skin''s own repair mechanisms to address scars, fine lines, enlarged pores, and more.","excerpt_fr":"L’un de nos soins MédiSpa les plus demandés stimule les mécanismes naturels de réparation de la peau pour cibler cicatrices, ridules, pores dilatés et bien plus.","body":"Micro-needling is one of the most evidence-backed, results-driven treatments in modern aesthetics. At Spa Rivier MediSpa, we offer two technologies — DermaRoller and the advanced Xcellaris Pro — tailored to different skin needs and treatment goals.\n\n## The Mechanism: Controlled Micro-Injury\n\nMicro-needling works by creating thousands of microscopic punctures in the skin using ultra-fine needles. These controlled micro-injuries trigger the skin''s natural wound-healing response — stimulating the production of collagen and elastin, the two proteins responsible for firm, smooth, youthful skin.\n\nThe needles do not cause scarring. They are calibrated to reach the precise depth needed to activate the repair cascade without damaging the epidermis. A topical anaesthetic is applied 30 minutes before treatment, so most clients experience little to no discomfort.\n\n## DermaRoller vs. Xcellaris Pro\n\nOur DermaRoller treatment is the classic micro-needling protocol — ideal for clients new to the treatment, focusing on skin texture, mild scarring, and fine line refinement. Starting at $510 per session, it is the most accessible entry point to professional needling.\n\nThe Xcellaris Pro adds radiofrequency (RF) energy to the micro-needling process. The combination of physical needling and RF thermal energy produces significantly enhanced skin tightening, collagen remodelling, and pore reduction. It is particularly effective for skin laxity, deeper acne scarring, and clients over 40 seeking anti-ageing benefits. Xcellaris Pro sessions start at $425.\n\n## Who Is It For?\n\nMicro-needling is suitable for most skin types and tones. It is particularly beneficial for those dealing with acne scarring, enlarged pores, uneven texture, fine lines and wrinkles, stretch marks, and even hair loss on the scalp. It is not suitable for active acne breakouts, certain skin conditions, or during pregnancy.\n\nA complimentary consultation with our MediSpa specialists will confirm whether micro-needling is right for you and which protocol will deliver the best results for your specific concerns.\n\n[Book a MediSpa Consultation](/medispa)","body_fr":"Le micro-needling est l’un des soins les plus documentés et les plus efficaces de l’esthétique moderne. Au MédiSpa Spa Rivier, nous proposons deux technologies — DermaRoller et Xcellaris Pro — adaptées à différents besoins et objectifs.\n\n## Le mécanisme : une micro-lésion contrôlée\n\nLe micro-needling crée des milliers de micro-perforations dans la peau à l’aide d’aiguilles ultrafines. Ces micro-lésions contrôlées déclenchent la réponse naturelle de cicatrisation et stimulent la production de collagène et d’élastine, les protéines responsables d’une peau ferme, lisse et jeune.\n\nLes aiguilles ne causent pas de cicatrices. Elles sont réglées à la profondeur précise nécessaire pour activer la réparation sans endommager l’épiderme. Un anesthésiant topique est appliqué 30 minutes avant le soin, si bien que la plupart des clientes ressentent peu ou pas d’inconfort.\n\n## DermaRoller ou Xcellaris Pro\n\nLe soin DermaRoller est le protocole classique de micro-needling, idéal pour découvrir ce traitement et cibler la texture, les cicatrices légères et les ridules. À partir de 510 $ la séance, c’est la porte d’entrée la plus accessible vers le needling professionnel.\n\nXcellaris Pro ajoute une énergie radiofréquence au micro-needling. L’association des aiguilles et de la chaleur RF améliore le raffermissement, le remodelage du collagène et la réduction des pores. Les séances commencent à 425 $.\n\n## À qui s’adresse ce soin ?\n\nLe micro-needling convient à la plupart des types et teints de peau. Il est particulièrement bénéfique pour les cicatrices d’acné, les pores dilatés, la texture irrégulière, les ridules, les vergetures et même la perte de cheveux du cuir chevelu. Il ne convient pas à l’acné active, à certaines affections cutanées ni à la grossesse.\n\nUne consultation gratuite avec nos spécialistes du MédiSpa confirmera si le micro-needling vous convient et quel protocole répondra le mieux à vos préoccupations.\n\n[Réserver une consultation MédiSpa](/medispa)"}'::jsonb, 3),
      ('articles', 'champagne-afternoon-tea', '{"title":"Champagne Afternoon Tea: A Spa Rivier Tradition Worth Savouring","title_fr":"Le thé de l’après-midi au champagne : une tradition Spa Rivier à savourer","category":"Gourmet","category_fr":"Gastronomie","image":"/images/gifts/candle-diffuser-tray.jpg","featured":false,"date":"March 30, 2026","date_fr":"30 mars 2026","read_time":"3 min read","read_time_fr":"3 min de lecture","author":"Spa Rivier Gourmet","author_fr":"Spa Rivier Gastronomie","excerpt":"Every Thursday through Saturday, Spa Rivier''s Gourmet transforms into the finest afternoon tea destination in Northern BC. Here''s what makes it so extraordinary.","excerpt_fr":"Du jeudi au samedi, Spa Rivier Gastronomie se transforme en la destination de thé de l’après-midi la plus raffinée du nord de la C.-B. Voici ce qui la rend si exceptionnelle.","body":"There is something deeply civilised about afternoon tea. The slow ceremony of it — fine china, tiered stands, crustless sandwiches, warm scones — demands that you pause, breathe, and be present with the people across the table from you.\n\nAt Spa Rivier Gourmet, we have built our afternoon tea service around that philosophy. Served Thursday through Saturday from 2:00 to 5:00 PM, it is one of the most beloved traditions we offer — and one of the most frequently gifted experiences in our certificate collection.\n\n## What''s on the Menu\n\nOur head chef curates the menu seasonally, but the architecture is constant: a first tier of finger sandwiches crafted from locally sourced ingredients, a second tier of house-baked scones served warm with clotted cream and Spa Rivier house jam, and a third tier of petit fours, macarons, and seasonal pastries.\n\nEvery service includes a selection from our curated loose-leaf tea collection — or, for those who prefer, a glass of champagne or sparkling rosé. We also accommodate dietary requirements with advance notice.\n\n## The Perfect Occasion\n\nAfternoon tea at Spa Rivier has become the go-to celebration for birthdays, bridal showers, mother-daughter outings, and promotion lunches. Minimum two guests, advance reservation required. We recommend booking at least 48 hours ahead, especially on weekends.\n\n[Reserve Afternoon Tea](/gourmet)","body_fr":"Le thé de l’après-midi possède quelque chose de profondément raffiné. Son rituel lent — porcelaine délicate, présentoirs étagés, sandwichs sans croûte et scones chauds — vous invite à faire une pause, à respirer et à être pleinement présente avec les personnes autour de la table.\n\nChez Spa Rivier Gastronomie, nous avons construit notre service autour de cette philosophie. Servi du jeudi au samedi de 14 h à 17 h, il est l’une de nos traditions les plus appréciées et l’une des expériences les plus offertes de notre collection de certificats.\n\n## Au menu\n\nNotre chef compose le menu au fil des saisons, mais sa structure demeure : un premier étage de sandwichs raffinés préparés avec des ingrédients locaux, un deuxième étage de scones maison servis chauds avec crème caillée et confiture Spa Rivier, puis un troisième étage de petits fours, macarons et pâtisseries de saison.\n\nChaque service comprend une sélection de notre collection de thés en feuilles, ou, pour celles qui le préfèrent, une coupe de champagne ou de rosé pétillant. Les besoins alimentaires particuliers sont également pris en compte sur préavis.\n\n## L’occasion parfaite\n\nLe thé de l’après-midi chez Spa Rivier est devenu le rendez-vous privilégié pour les anniversaires, fêtes prénuptiales, sorties mère-fille et déjeuners de célébration. Deux personnes minimum et réservation à l’avance sont requises. Nous recommandons de réserver au moins 48 heures à l’avance, surtout les fins de semaine.\n\n[Réserver un thé de l’après-midi](/gourmet)"}'::jsonb, 4),
      ('articles', 'gift-hamper-guide', '{"title":"The Art of the Perfect Gift: Choosing from the Spa Rivier Collection","title_fr":"L’art du cadeau parfait : bien choisir dans la collection Spa Rivier","category":"Gifts","category_fr":"Cadeaux","image":"/images/gifts/gift-assortment.jpg","featured":false,"date":"March 18, 2026","date_fr":"18 mars 2026","read_time":"4 min read","read_time_fr":"4 min de lecture","author":"The Spa Rivier Gifting Team","author_fr":"L’équipe cadeaux Spa Rivier","excerpt":"The hard part of gifting is not the wrapping — it is knowing what to choose. Here is how our collection is organised, and how to find the right thing in it.","excerpt_fr":"Le plus difficile n’est pas l’emballage, c’est de savoir quoi choisir. Voici comment notre collection est organisée et comment y trouver le bon cadeau.","body":"The best gifts don''t just delight in the moment — they communicate something. That you know this person. That you thought about them specifically. That they are worth the care it took to put this together.\n\nThat is why our gift collection is not a shelf of assorted baskets. Every piece in it was chosen the way you would choose it — because someone would be genuinely glad to receive it.\n\n## Start with the Category, Not the Price\n\nThe collection is grouped into five categories, and the quickest way to narrow it down is to pick the one that sounds like the person rather than the one that matches your budget. Hampers & Sets for the recipient who is hard to read. Skincare & Beauty for the one who has a routine and is particular about it. Lifestyle for the home-maker. Jewellery & Accessories for the person who notices detail. Gourmet for the host.\n\nInside those you will find silk robes and cashmere, hand-poured candles and fragrance, the skincare we use in our own treatment rooms, and — newly added — our Champagne Afternoon Tea, the brunch charcuterie board, and Gimber ginger concentrate for anyone who would rather toast with something other than wine.\n\n## The Presentation\n\nWhatever you choose is finished with gold tissue and champagne ribbon, and we will hand-letter the note. The presentation is part of the gift. Same-day collection in store, and local delivery within Quesnel.\n\n## When You Genuinely Cannot Decide\n\nThen do not. A gift certificate is not the lazy choice when it hands the recipient their own — ours run from $50 to $1,000 across seven tiers, they are redeemable against everything we offer, and they sit on the same page as the collection.\n\n[Browse the Gift Collection](/giftware)","body_fr":"Les meilleurs cadeaux ne font pas que réjouir sur le moment : ils expriment quelque chose. Ils montrent que vous connaissez cette personne, que vous avez pensé à elle et qu’elle mérite le soin consacré à cette attention.\n\nC’est pourquoi notre collection de cadeaux n’est pas un simple rayon de paniers assortis. Chaque article y a été choisi comme vous l’auriez choisi vous-même : parce qu’il fera vraiment plaisir à quelqu’un.\n\n## Commencez par la catégorie, pas par le prix\n\nLa collection est répartie en cinq catégories, et le plus simple est de choisir celle qui ressemble à la personne plutôt que celle qui correspond à votre budget. Coffrets & Paniers pour celle ou celui qu’on cerne mal. Beauté & Soins pour qui a une routine bien à soi. Art de Vivre pour qui aime sa maison. Bijoux & Accessoires pour qui remarque les détails. Gastronomie pour qui reçoit.\n\nVous y trouverez des peignoirs en soie et du cachemire, des bougies coulées à la main et des parfums, les soins que nous utilisons dans nos propres cabines, et — nouveauté — notre Thé de l’Après-Midi au Champagne, la planche de charcuterie du brunch et le concentré de gingembre Gimber.\n\n## La présentation\n\nQuel que soit votre choix, il est terminé avec du papier de soie doré et un ruban champagne, et nous calligraphions la note à la main. La présentation fait partie du cadeau. Collecte le jour même en boutique et livraison locale à Quesnel.\n\n## Si vous hésitez vraiment\n\nAlors n’hésitez plus : le certificat cadeau laisse le choix à la personne qui le reçoit. Les nôtres vont de 50 $ à 1 000 $ en sept paliers, sont échangeables pour tout ce que nous offrons, et se trouvent sur la même page que la collection.\n\n[Découvrir la collection de cadeaux](/giftware)"}'::jsonb, 5);
  FOR l IN SELECT DISTINCT list FROM seed_items LOOP
    IF NOT EXISTS (SELECT 1 FROM public.site_items WHERE list = l) THEN
      INSERT INTO public.site_items (list, slug, data, sort_order)
        SELECT list, slug, data, sort_order FROM seed_items WHERE list = l;
    END IF;
  END LOOP;
END
$seed$;

