ALTER TABLE public.services ADD COLUMN IF NOT EXISTS price_series text NOT NULL DEFAULT '';
-- Whatever the old category rule is called, it gives way to one with MediSpa.
DO $cat$
DECLARE c text;
BEGIN
  FOR c IN SELECT conname FROM pg_constraint
           WHERE conrelid = 'public.services'::regclass AND contype = 'c'
             AND pg_get_constraintdef(oid) LIKE '%category%' LOOP
    EXECUTE format('ALTER TABLE public.services DROP CONSTRAINT %I', c);
  END LOOP;
END
$cat$;
ALTER TABLE public.services ADD CONSTRAINT services_category_check CHECK (category IN ('spa','salon','medispa'));

