-- ── 5. Photos the admin uploads ──────────────────────────────────────────────
-- Public to read; only admins may add, replace or remove files.
INSERT INTO storage.buckets (id, name, public, file_size_limit, allowed_mime_types)
VALUES ('site', 'site', true, 10485760,
        ARRAY['image/jpeg','image/png','image/webp','image/gif','image/svg+xml'])
ON CONFLICT (id) DO UPDATE
  SET public = true,
      file_size_limit = EXCLUDED.file_size_limit,
      allowed_mime_types = EXCLUDED.allowed_mime_types;

DROP POLICY IF EXISTS "site bucket: admins insert" ON storage.objects;
DROP POLICY IF EXISTS "site bucket: admins update" ON storage.objects;
DROP POLICY IF EXISTS "site bucket: admins delete" ON storage.objects;
CREATE POLICY "site bucket: admins insert" ON storage.objects
  FOR INSERT TO authenticated WITH CHECK (bucket_id = 'site' AND public.is_admin());
CREATE POLICY "site bucket: admins update" ON storage.objects
  FOR UPDATE TO authenticated USING (bucket_id = 'site' AND public.is_admin());
CREATE POLICY "site bucket: admins delete" ON storage.objects
  FOR DELETE TO authenticated USING (bucket_id = 'site' AND public.is_admin());

-- ── 6. Supabase Studio access ────────────────────────────────────────────────
-- Studio opens only for admins with studio_access (functions/studio-gate).
-- Today's admins keep the access they had; admins added later start without.
DO $studio$
BEGIN
  IF NOT EXISTS (SELECT 1 FROM information_schema.columns
                 WHERE table_schema = 'public' AND table_name = 'profiles' AND column_name = 'studio_access') THEN
    ALTER TABLE public.profiles ADD COLUMN studio_access boolean NOT NULL DEFAULT false;
    UPDATE public.profiles SET studio_access = true WHERE role = 'admin';
  END IF;
END
$studio$;

-- Who may change studio_access: someone who has it, or the database itself
-- (the SQL editor and server functions, where there is no signed-in user).
CREATE OR REPLACE FUNCTION public.guard_studio_access()
RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path = public AS $$
BEGIN
  IF NEW.studio_access IS DISTINCT FROM OLD.studio_access AND auth.uid() IS NOT NULL THEN
    IF NOT EXISTS (SELECT 1 FROM public.profiles
                   WHERE id = auth.uid() AND role = 'admin' AND studio_access) THEN
      RAISE EXCEPTION 'Only someone with Supabase Studio access can change it';
    END IF;
  END IF;
  -- Studio access goes with the admin role.
  IF NEW.role <> 'admin' THEN NEW.studio_access := false; END IF;
  RETURN NEW;
END; $$;

DROP TRIGGER IF EXISTS trg_guard_studio_access ON public.profiles;
CREATE TRIGGER trg_guard_studio_access
  BEFORE UPDATE ON public.profiles
  FOR EACH ROW EXECUTE FUNCTION public.guard_studio_access();

COMMIT;
